import { HugeiconsIcon } from "@hugeicons/react";
import BadgeCheckIcon from "@hugeicons/core-free-icons/BadgeCheckIcon";
import BellIcon from "@hugeicons/core-free-icons/BellIcon";
import CreditCardIcon from "@hugeicons/core-free-icons/CreditCardIcon";
import LogOutIcon from "@hugeicons/core-free-icons/LogOutIcon";

import { Avatar, AvatarFallback, AvatarImage } from "@/registry/erbium/ui/avatar";
import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/registry/erbium/ui/dropdown-menu";

export function DropdownMenuAvatar() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={<Button variant="ghost" size="icon" className="rounded-[35%]" />}
      >
        <Avatar>
          <AvatarImage src="https://github.com/shadcn.png" alt="shadcn" />
          <AvatarFallback>LR</AvatarFallback>
        </Avatar>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        <DropdownMenuGroup>
          <DropdownMenuItem>
            <HugeiconsIcon icon={BadgeCheckIcon} />
            Account
          </DropdownMenuItem>
          <DropdownMenuItem>
            <HugeiconsIcon icon={CreditCardIcon} />
            Billing
          </DropdownMenuItem>
          <DropdownMenuItem>
            <HugeiconsIcon icon={BellIcon} />
            Notifications
          </DropdownMenuItem>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <HugeiconsIcon icon={LogOutIcon} />
          Sign Out
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { DropdownMenuAvatar } from "../examples/upstream/dropdown-menu-avatar";

const Example = () => <DropdownMenuAvatar />;

export default Example;
